	let oldVNode = component._vnode,
		oldDom = oldVNode._dom,
		parentDom = component._parentDom;

	if (parentDom) {
		let commitQueue = [],
			refQueue = [];

		const newVNode = assign({}, oldVNode);
		newVNode._original = oldVNode._original + 1;

